mkdir -p src && cat > src/shapes.py <<'EOF'
def compute_area(width, height):
    return width * height

class Rectangle:
    def __init__(self, width, height):
        self.width = width
        self.height = height
    def area(self):
        return compute_area(self.width, self.height)

class Box:
    def __init__(self, width, height):
        self.width = width
        self.height = height
    def area(self):
        return compute_area(self.width, self.height)
EOF
